"""Exact engineering settings for the six C136539 exposure comparisons.

These settings select physical scenes. They do not define legal endangerment.
"""

from math import hypot


PREFIX = 'heldout__C136539__NRS-484B-600-1b__motor_vehicle_driver__'
CASES = {
    'slow_person_exposure': (2.0, 'pedestrian', 0.4),
    'moderate_person_exposure': (5.0, 'pedestrian', 0.4),
    'fast_person_exposure': (8.0, 'pedestrian', 0.4),
    'clearance_reference': (5.0, 'pedestrian', 2.0),
    'property_near': (5.0, 'property', 0.4),
    'property_far': (5.0, 'property', 2.0),
}


def case_settings(config):
    if (config.get('law_id'), config.get('cell_id'), config.get('actor')) != (
            'NRS-484B-600-1b', 'C136539', 'motor_vehicle_driver'):
        raise ValueError('Exposure case identity differs')
    case_id = config.get('selected_case_id', '')
    if not case_id.startswith(PREFIX):
        raise ValueError('Unknown exact exposure case')
    suffix = case_id[len(PREFIX):]
    if suffix not in CASES:
        raise ValueError('Unknown exact exposure case')
    speed, kind, lateral = CASES[suffix]
    if (config.get('rate_hz'), config.get('frames')) != (20, 160):
        raise ValueError('Exposure cases require 160 frames at 20 Hz')
    if config.get('requested_speed_mps') != speed or config.get('exposed_kind') != kind or config.get('outside_edge_m') != lateral:
        raise ValueError('Exposure case engineering setting differs')
    if config.get('construction_probe_only') is not True:
        raise ValueError('Construction case may not masquerade as delivery')
    return {'case_id': case_id, 'speed_mps': speed, 'exposed_kind': kind,
            'outside_edge_m': lateral}


def exposed_transform_point(route, *, outside_edge_m, waypoint_index=8):
    if len(route) <= waypoint_index or outside_edge_m < 0:
        raise ValueError('Exposure route or lateral placement invalid')
    waypoint = route[waypoint_index]
    forward = waypoint.transform.get_forward_vector()
    norm = hypot(forward.x, forward.y)
    if norm < 1e-6:
        raise ValueError('Exposure route tangent undefined')
    point = waypoint.transform.location
    offset = waypoint.lane_width / 2 + outside_edge_m
    return [point.x - forward.y / norm * offset,
            point.y + forward.x / norm * offset, point.z]


def spawn_exposed(world, carla, route, settings):
    """Spawn an actual participant or fixed property body at the requested verge."""
    point = exposed_transform_point(route, outside_edge_m=settings['outside_edge_m'])
    kind = settings['exposed_kind']
    blueprint_id = ('walker.pedestrian.0001' if kind == 'pedestrian'
                    else 'vehicle.tesla.model3')
    blueprint = world.get_blueprint_library().find(blueprint_id)
    transform = carla.Transform(carla.Location(*point), route[8].transform.rotation)
    actor = world.try_spawn_actor(blueprint, transform)
    if actor is None:
        raise ValueError('Native exposed ' + kind + ' spawn failed')
    if kind == 'property':
        actor.set_simulate_physics(False)
    return actor

"""Four synchronized original RGB source streams for exposure probes."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8, 0, 10), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown exposure source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior exposure camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original exposure camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Exposure source encoder failed")


class ExposureCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named exposure source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original exposure camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original exposure camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Exposure source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original exposure source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original exposure camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

import sys
import unittest
from pathlib import Path
from types import SimpleNamespace as NS

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from exposure_camera import CAMERAS, ExposureCameraCapture


class Sensor:
    def __init__(self):
        self.callback = None
        self.destroyed = False

    def listen(self, callback):
        self.callback = callback

    def stop(self):
        pass

    def destroy(self):
        self.destroyed = True


class Blueprint:
    def __init__(self):
        self.attributes = {}

    def set_attribute(self, name, value):
        self.attributes[name] = value


class World:
    def __init__(self):
        self.sensors = []

    def get_blueprint_library(self):
        return NS(find=lambda _: Blueprint())

    def spawn_actor(self, blueprint, transform, attach_to):
        sensor = Sensor()
        self.sensors.append(sensor)
        return sensor


class Sink:
    def __init__(self):
        self.frames = []

    def write(self, image):
        self.frames.append(image.frame)


class CameraCaptureTests(unittest.TestCase):
    def test_four_sources_join_and_missing_source_rejected(self):
        world = World()
        carla = NS(Location=lambda *values: values, Rotation=lambda *values: values,
                   Transform=lambda location, rotation: (location, rotation))
        sinks = {name: Sink() for name in CAMERAS}
        cameras = ExposureCameraCapture(world, carla, object(), sinks)
        self.assertEqual(len(world.sensors), 4)
        for sensor, (name, spec) in zip(world.sensors, CAMERAS.items()):
            width, height = spec[2]
            sensor.callback(NS(frame=20, width=width, height=height))
        cameras.wait_for_frame(20, timeout_s=0.01)
        self.assertEqual(cameras.verify([20]), {name: 1 for name in CAMERAS})
        with self.assertRaisesRegex(ValueError, "Missing or extra"):
            cameras.verify([20, 21])
        world.sensors[0].callback(NS(frame=20, width=1920, height=1080))
        with self.assertRaisesRegex(ValueError, "callback failed"):
            cameras.wait_for_frame(20, timeout_s=0.01)
        cameras.close()
        self.assertTrue(all(sensor.destroyed for sensor in world.sensors))


if __name__ == "__main__":
    unittest.main()
